from typing import Any, Dict

import os
import yaml




def get_directory_size(directory: str) -> int:
    """Get the size of a directory in bytes"""
    total = 0
    with os.scandir(directory) as it:
        for entry in it:
            if entry.is_file():
                total += entry.stat().st_size
            elif entry.is_dir():
                total += get_directory_size(entry.path)
    return total


